	/** 
	 * jumpstart the process by instantiating2 Agency
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		agencyId = AgencyService.getAgencyInstance()
		.createAgency( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		AgencyService.getAgencyInstance()
				.createAgency( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.agencySubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Agency : " + successValue.getAgencyId());
							  if (successValue.getAgencyId().equals(agencyId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfAgencyList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Agency test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on agency consumed")
					);
			subscriber.agencySubscribe( agencyId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Agency : " + successValue.getAgencyId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfAgencyList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on agency for agencyId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Agency. 
	 */
	protected Agency read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Agency" );

		Agency entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Agency with primary key" );
		msg.append( agencyId );
		
		AgencyFetchOneSummary fetchOneSummary = new AgencyFetchOneSummary( agencyId );

		try {
			entity = AgencyService.getAgencyInstance().getAgency( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Agency " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Agency.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Agency." );

		StringBuilder msg = new StringBuilder( "Failed to update a Agency : " );        
		Agency entity = read();
		UpdateAgencyCommand command = generateUpdateCommand();
		command.setAgencyId(entity.getAgencyId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Agency." );

			// for use later on...
			agencyId = entity.getAgencyId();

			AgencyService proxy = AgencyService.getAgencyInstance();  

			proxy.updateAgency( command ).get();

			LOGGER.info( "-- Successfully saved Agency - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + agencyId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Agency.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Agency." );

		Agency entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Agency with id " + agencyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Agency with id " + agencyId );

			throw e;
		}

		try{
			AgencyService.getAgencyInstance().delete( new DeleteAgencyCommand( entity.getAgencyId() ) ).get();
			LOGGER.info( "-- Successfully deleted Agency with id " + agencyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Agency with id " + agencyId );

			throw e;
		}
	}

	/**
	 * get all Agencys.
	 */
	protected List<Agency> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Agencys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Agency : " );        
		List<Agency> collection  = new ArrayList<>();

		try {
			// call the static get method on the AgencyService
			collection = AgencyService.getAgencyInstance().getAllAgency();
			assertNotNull( collection, "An Empty collection of Agency was incorrectly returned.");
			
			// Now print out the values
			Agency entity = null;            
			Iterator<Agency> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAgencyId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

